import{_ as a,c as o,o as c,a0 as n}from"./chunks/framework.C1J0Vcxi.js";const _=JSON.parse('{"title":"Pend ISR 调度循环","description":"","frontmatter":{"title":"Pend ISR 调度循环","date":"2026-05-09T00:00:00.000Z","type":"description"},"headers":[],"relativePath":"docs/pend-isr.md","filePath":"docs/pend-isr.md"}'),d={name:"docs/pend-isr.md"};function t(r,e,s,i,p,l){return c(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="pend-isr-调度循环" tabindex="-1">Pend ISR 调度循环 <a class="header-anchor" href="#pend-isr-调度循环" aria-label="Permalink to &quot;Pend ISR 调度循环&quot;">​</a></h1><p>抢占由 Pend（软件中断）触发，在中断处理函数中完成 executor 切换。</p><h2 id="调度流程" tabindex="-1">调度流程 <a class="header-anchor" href="#调度流程" aria-label="Permalink to &quot;调度流程&quot;">​</a></h2><p>在 RISC-V 上，调度 ISR 为 <code>MachineSoft</code>（Machine Software Interrupt）。由 <code>#[main]</code> 宏自动生成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MachineSoft ISR:</span></span>
<span class="line"><span>    clear_pend()                      // 清除 MSI 挂起标志，检查 PEND_MARKER</span></span>
<span class="line"><span>    if PEND_MARKER == true:           // 调度器触发的 MSI</span></span>
<span class="line"><span>        loop:                         // MIE=0，临界区</span></span>
<span class="line"><span>            token = try_preempt()     // 检查是否有更高优先级就绪</span></span>
<span class="line"><span>            if None: break</span></span>
<span class="line"><span>            enable_interrupts()       // MIE=1，允许被再次抢占</span></span>
<span class="line"><span>            run(token)                // 运行新 executor（可被中断）</span></span>
<span class="line"><span>            disable_interrupts()      // MIE=0，恢复原子操作</span></span>
<span class="line"><span>            complete_executor()       // 弹出已完成的 executor</span></span>
<span class="line"><span>    else:                             // 外部 MSI（硬件/跨核）</span></span>
<span class="line"><span>        __Inner_MachineSoft(tf)       // 调用用户定义的中断处理</span></span></code></pre></div><h2 id="pend-marker" tabindex="-1">PEND_MARKER <a class="header-anchor" href="#pend-marker" aria-label="Permalink to &quot;PEND_MARKER&quot;">​</a></h2><p><code>platform::PEND_MARKER</code> 是一个 <code>AtomicBool</code>，用于区分 MSI 来源：</p><table tabindex="0"><thead><tr><th>PEND_MARKER</th><th>来源</th><th>动作</th></tr></thead><tbody><tr><td><code>true</code></td><td><code>platform::pend()</code>（调度器）</td><td>运行优先级抢占调度循环</td></tr><tr><td><code>false</code></td><td>外部 MSI（硬件/跨核 IPI）</td><td>调用 <code>__Inner_MachineSoft</code>（用户定义）</td></tr></tbody></table><p><code>pend()</code> 在触发 MSI 前将 <code>PEND_MARKER</code> 置 <code>true</code>，<code>clear_pend()</code> 读取并清除它。</p><h2 id="pend-与-ipi-设备" tabindex="-1">pend 与 IPI 设备 <a class="header-anchor" href="#pend-与-ipi-设备" aria-label="Permalink to &quot;pend 与 IPI 设备&quot;">​</a></h2><p><code>pend()</code> / <code>clear_pend()</code> 不再直接操作固定硬件寄存器，而是经 driver registry 取 IPI 设备（<code>driver::ipi()</code>）。<code>pend()</code> 内部置 <code>PEND_MARKER</code> 后调用 <code>driver::ipi().send()</code>，<code>clear_pend()</code> 在 ISR 早期 <code>swap</code> 掉 <code>PEND_MARKER</code> 后调用 <code>driver::ipi().clear()</code>。具体 IPI 硬件实现（QEMU virt 的 CLINT MSIP / K3 的 PXA IPI）由板级 driver 的 <code>Ipi</code> trait 实现决定，平台层与调度器本身与硬件解耦。</p><h2 id="嵌套抢占" tabindex="-1">嵌套抢占 <a class="header-anchor" href="#嵌套抢占" aria-label="Permalink to &quot;嵌套抢占&quot;">​</a></h2><p><code>run(token)</code> 执行期间 <code>MIE=1</code>，允许更高优先级 executor 在当前 executor 的栈帧之上继续嵌套抢占。这是共享系统栈设计的关键：</p><ol><li>Executor A (prio 5) 正在运行</li><li>更高优先级任务就绪 → <code>pend()</code> 触发 MSI</li><li><code>MachineSoft</code> ISR 挂起当前执行流，保存 callee-saved 寄存器</li><li><code>try_preempt()</code> 返回 RunToken(prio 2)</li><li><code>enable_interrupts()</code> → <code>run(token)</code> 执行 Executor B (prio 2)</li><li>Executor B 运行期间又触发 MSI → 重复步骤 3-5 执行 Executor C (prio 0)</li><li>Executor C 完成 → <code>disable_interrupts()</code> → <code>complete_executor()</code> → 回到 Executor B</li><li>Executor B 完成 → 回到 Executor A → <code>restore callee-saved regs</code> → <code>mret</code></li></ol><h2 id="critical-section-与中断状态" tabindex="-1">critical_section 与中断状态 <a class="header-anchor" href="#critical-section-与中断状态" aria-label="Permalink to &quot;critical_section 与中断状态&quot;">​</a></h2><p><code>try_preempt()</code> 和 <code>complete_executor()</code> 内部使用 <code>critical_section::with</code>。在 RISC-V 上该原语通过禁/使中断实现。Pend ISR 循环中 MIE 已经为 0，因此 <code>critical_section</code> 的开销仅为增加/减少一个嵌套计数——功能上冗余但无副作用，保证代码在不依赖中断状态的上下文中也可安全调用。</p>`,16)])])}const u=a(d,[["render",t]]);export{_ as __pageData,u as default};
